/** Mac 风格主题的兜底快捷键（`macKeyAction`）：⌘ 与 Ctrl 两份都登记。 */
const MAC_KEYS: Record<string, string> = {
  "meta+,": "look",
  "ctrl+,": "look",
  "meta+k": "filesearch",
  "ctrl+k": "filesearch",
  "ctrl+meta+s": "sessions",
  "ctrl+alt+s": "sessions",
  "meta+.": "interrupt",
  "ctrl+.": "interrupt",
};

/** 设置里「Mac 快捷键」那一行：按平台给出键帽。 */
const MAC_KEY_HINTS: [(mac: boolean) => string[], string][] = [
  [(m) => (m ? ["⌘", ","] : ["Ctrl", ","]), "设置"],
  [(m) => (m ? ["⌘", "K"] : ["Ctrl", "K"]), "搜索"],
  [(m) => (m ? ["⌃", "⌘", "S"] : ["Ctrl", "Alt", "S"]), "收起 / 展开左栏"],
  [(m) => (m ? ["⌘", "."] : ["Ctrl", "."]), "中断当前回复"],
  [() => ["Esc"], "逐层关闭弹层"],
];

/** 出厂就带的组合键；用户改过的以 localStorage 里的为准。 */
const DEFAULT_KEYS: Record<string, string> = { notes: "ctrl+shift+b", filesearch: "ctrl+shift+f" };

/** The browser owns these; a page must never swallow them. */
const RESERVED_KEYS = new Set([
  "ctrl+w",
  "ctrl+r",
  "ctrl+t",
  "ctrl+n",
  "ctrl+l",
  "ctrl+p",
  "ctrl+s",
  "ctrl+o",
  "ctrl+shift+i",
  "ctrl+shift+j",
  "ctrl+shift+c",
  "ctrl+shift+delete",
  "meta+w",
  "meta+r",
  "meta+t",
  "meta+n",
  "meta+l",
  "meta+q",
  "alt+f4",
  "alt+left",
  "alt+right",
  "f1",
  "f5",
  "f11",
  "f12",
]);
const MOD_KEY_NAMES = new Set(["control", "shift", "alt", "meta", "os", "altgraph"]);

/** “ctrl+shift+k” for a keydown, or null for a bare modifier press. */
function comboOf(ev: KeyboardEvent): string | null {
  const raw = ev.key;
  if (!raw || MOD_KEY_NAMES.has(raw.toLowerCase())) return null;
  const parts: string[] = [];
  if (ev.ctrlKey) parts.push("ctrl");
  if (ev.altKey) parts.push("alt");
  if (ev.shiftKey) parts.push("shift");
  if (ev.metaKey) parts.push("meta");
  parts.push(raw === " " ? "space" : raw.toLowerCase());
  return parts.join("+");
}

/** Modifier combos, plus bare F2–F10 — the one bare-key class this page accepts. */
function shortcutAllowed(combo: string): boolean {
  if (RESERVED_KEYS.has(combo)) return false;
  const parts = combo.split("+");
  if (parts.length > 1) return true;
  return /^f([2-9]|10)$/.test(parts[0] ?? "");
}

/** “Ctrl+Shift+K” for display. */
/** 把一个数夹进 [min, max]；max 比 min 还小时取 min（窗口比 dialog 还窄时不出现负尺寸）。 */
function clampNum(value: number, min: number, max: number): number {
  return Math.round(Math.max(min, Math.min(Math.max(min, max), value)));
}

function keyLabel(combo: string): string {
  return combo
    .split("+")
    .map((part) => (part.length === 1 ? part.toUpperCase() : part.charAt(0).toUpperCase() + part.slice(1)))
    .join("+");
}

function loadKeys(): Record<string, string> {
  try {
    const raw = localStorage.getItem("pi.keys");
    if (!raw) return {};
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return {};
    const out: Record<string, string> = {};
    for (const { id } of SHORTCUTS) {
      const value = (parsed as Record<string, unknown>)[id];
      if (typeof value === "string" && shortcutAllowed(value)) out[id] = value;
    }
    return out;
  } catch {
    return {};
  }
}

function saveKeys(keys: Record<string, string>): void {
  try {
    localStorage.setItem("pi.keys", JSON.stringify(keys));
  } catch {
    // storage blocked or full: the bindings still work until the next reload
  }
}

/** Opens a link in a new tab, but only if it stays on this origin (previews are same-origin /raw/…). */
/** 外链只放行 http(s)，并且始终交给一个带 rel=noopener 的真链接去开（和 openSameOrigin 同一个理由）。 */
function openExternal(url: string): void {
  const safe = safeExternalUrl(url);
  if (!safe) return;
  const a = document.createElement("a");
  a.href = safe;
  a.target = "_blank";
  a.rel = "noopener noreferrer";
  a.click();
}

function openSameOrigin(url: string): void {
  const target = new URL(url, location.href);
  if (target.origin !== location.origin) return;
  // A real anchor with rel=noopener does the same job as window.open without handing the URL to a
  // navigation sink: the origin check above is the gate, this is just the click.
  const a = document.createElement("a");
  a.href = target.href;
  a.target = "_blank";
  a.rel = "noopener noreferrer";
  a.click();
}

/**
 * 字号：一根连续滑杆（0.8–2.0，步长 1%），不再是四颗 chip。
 *
 * 老的四档没消失，改行「轨上的刻度」：`SIZE_STOPS` 既是刻度字的位置，也是磁吸点 ——
 * 指针拖到 ±1.2% 以内会吸上去，点刻度直接落档。键盘不吃磁吸（每按一下是 1%，吸了会永远卡在刻度上）。
 * 取舍与样张见 `.scratch/font-slider/`，D 记录见 docs/DECISIONS.md。
 */
const SIZE_MIN = 0.8;
const SIZE_MAX = 2;
const SIZE_STEP = 0.01;
const SIZE_STOPS = [0.9, 1, 1.12, DEFAULT_SCALE];
/** 轨道上带数字的刻度：0.8 起每 0.2 一档。**六根滑杆共用这一套**（全局字号 + 五块），
 *  只放各自那几个档位的话数字全挤在轨道左半边，六根看着不像同一款；磁吸档位另算（`SIZE_STOPS` / `REGION_STOPS`）。 */
const SIZE_MARKS: number[] = (() => {
  const out: number[] = [];
  for (let i = 0; i * 0.2 <= SIZE_MAX - SIZE_MIN + 1e-9; i++) out.push(SIZE_MIN + i * 0.2);
  return out;
})();
/** 磁吸半径：0.012 = 1.2%，在 480px 的轨上大约 5px。 */
const SIZE_SNAP = 0.012;

/** 值 → 轨道位置 0..1（两端夹住，浮点误差不会把填充画到轨外）。 */
const sizePct = (v: number): number => Math.min(1, Math.max(0, (v - SIZE_MIN) / (SIZE_MAX - SIZE_MIN)));


/** 夹进 0.8–2.0 并取两位小数：prefs 里只存得下这种值（滑杆的 step 就是 1%）。 */
const clampScale = (v: number): number => Math.round(Math.min(SIZE_MAX, Math.max(SIZE_MIN, v)) * 100) / 100;

/**
 * 设置里每颗布局 chip 的那张小示意图（46×30，纯 CSS 画的块）。不引图片：设置面板要能离线
 * 打开，也不想为四张缩略图多一条资源路径。画的是「行 / 列怎么摆」，不追求像素级复刻。
 */
function layoutDemo(id: LayoutId): HTMLElement {
  const box = el("span", `layout-demo layout-${id}`);
  box.setAttribute("aria-hidden", "true");
  const bar = (cls: string, cells = 0): HTMLElement => {
    const node = el("span", cls);
    for (let i = 0; i < cells; i += 1) node.append(el("span", "ld-cell"));
    box.append(node);
    return node;
  };
  bar("ld-top");
  if (id === "a") {
    bar("ld-row ld-row-tabs", 3);
    bar("ld-row ld-row-chips", 4);
    bar("ld-body");
  } else if (id === "b") {
    bar("ld-row ld-row-one", 4);
    bar("ld-body");
  } else if (id === "c") {
    bar("ld-rail", 3);
    bar("ld-body-wide");
  } else {
    bar("ld-icons", 4);
    for (let i = 0; i < 3; i += 1) box.append(el("span", "ld-line"));
    bar("ld-body-wide");
  }
  return box;
}

/**
 * 强调色只有 macOS 那一排八色（palette.ts，D353）：keys 是稳定 id，持久化在 `pi.prefs.macAccent` 里，
 * 不能翻译；tooltip 与 aria 走 `MAC_ACCENT_LABELS` + `tr()`。
 * D110 之前存的还是中文色名（那会儿是六色表）：`LEGACY_ACCENTS` 把它们换成旧 id，
 * 再由 `migrateThemePrefs()` 落成最近的那颗 macOS 色 —— 删掉它会把老用户的颜色静默清掉。
 */

/** Mac 那一排八色的显示名（macOS「系统设置 → 外观 → 强调色」的顺序）。 */
const MAC_ACCENT_LABELS: [string, string][] = [
  ["blue", tr("蓝色")],
  ["purple", tr("紫色")],
  ["pink", tr("粉色")],
  ["red", tr("红色")],
  ["orange", tr("橙色")],
  ["yellow", tr("黄色")],
  ["green", tr("绿色")],
  ["graphite", tr("石墨色")],
];

/** D438：强调色的两档饱和度。id 存在 `pi.prefs.accentTone`，不能翻译；显示名走 `tr()`。 */
const ACCENT_TONE_LABELS: [AccentTone, string][] = [
  ["vivid", tr("鲜艳")],
  ["muted", tr("柔和")],
];

/** D110 之前 `pi.prefs.accent` 存的是中文色名（六色那套），读到就换成旧 id（再由迁移表落成 macOS 八色）。 */
const LEGACY_ACCENTS: Record<string, string> = {
  冰蓝: "ice",
  青绿: "teal",
  紫: "violet",
  琥珀: "amber",
  玫瑰: "rose",
  银灰: "slate",
};

/** 读取一个字号值：滑杆是连续的，只夹范围、留两位小数（老的 0.9 / 1 / 1.12 / 1.25 原样还能读回来）。 */
function prefScale(raw: unknown): number {
  const scale = Number(raw);
  return Number.isFinite(scale) && scale > 0 ? clampScale(scale) : DEFAULT_PREFS.scale;
}

/**
 * D441：区域倍率逐块归一化。缺字段（老版本升上来 / 手改 localStorage）一律回 1.0，
 * 不让一条脏记录把某一块弄成 0 或 NaN —— 那会让 `zoom` 失效、整块内容消失。
 */
function prefRegionScale(raw: unknown): RegionScale {
  const src = raw && typeof raw === "object" ? (raw as Record<string, unknown>) : {};
  const out = regionScaleDefault();
  for (const id of REGION_IDS) {
    const v = Number(src[id]);
    if (Number.isFinite(v) && v > 0) out[id] = clampScale(v);
  }
  return out;
}

/**
 * 登录页在 `App` 之前就画出来了：先把已存或默认字号挂到 `#app` 上，
 * 否则新设备第一眼的登录页会停在 CSS 兜底的 100%。
 */
export function bootScale(): number {
  try {
    const raw = localStorage.getItem("pi.prefs");
    return raw ? prefScale(JSON.parse(raw)?.scale) : DEFAULT_PREFS.scale;
  } catch {
    return DEFAULT_PREFS.scale;
  }
}

function readPrefs(): Prefs {
  try {
    const raw = localStorage.getItem("pi.prefs");
    if (!raw) return { ...DEFAULT_PREFS, regionScale: regionScaleDefault(), lang: detectLang() };
    const p = JSON.parse(raw);
    // 中文色名（D110 前）→ 旧六色 id，剩下的一并交给纯函数（旧主题按明暗、旧强调色按最近色）。
    const legacyName = LEGACY_ACCENTS[String(p?.accent)];
    const next: Prefs = {
      scale: prefScale(p?.scale),
      ...migrateThemePrefs({ ...p, accent: legacyName ?? p?.accent }),
      // 没存过语言（第一次打开、或老版本升上来）就跟着浏览器走。
      lang: isLang(p?.lang) ? p.lang : detectLang(),
      wsCollapsed: Array.isArray(p?.wsCollapsed) ? p.wsCollapsed.filter((x: unknown): x is string => typeof x === "string") : [],
      // #97：布局走 layout.ts 的读口（它自己处理乱值 / 大小写），这里不再写一遍白名单。
      layout: layoutPref(p),
      settingsTab: p?.settingsTab === "conn" ? "conn" : "look",
      wsIntroSeen: p?.wsIntroSeen === true,
      // 只有明确写着 false 的（新用户第一次存盘）才算没弹过；升级上来的老用户已经在用自己的主题，不打扰。
      themeIntroSeen: p?.themeIntroSeen !== false,
      // D365：只有明确写着 false 的才算关（老版本升上来没这个键＝开着）。
      retellHint: p?.retellHint !== false,
      // #661：同上 —— 老版本升上来没有这个键，当作开着。
      githubCards: p?.githubCards !== false,
      // #666：这个反过来了 —— 老版本升上来没有这个键按**关**（默认值翻了，只有显式 true 才算开）。
      githubAutoPanel: p?.githubAutoPanel === true,
      // D421：同样没有「旧版本没这个键」的问题 —— 三档都按默认值来（只有用户自己动过才有这个键）。
      longCardUser: p?.longCardUser !== false,
      longCardAssistant: p?.longCardAssistant === true,
      longCardTool: p?.longCardTool === true,
      // D441：五块区域倍率（叠在 scale 上相乘）。没存过就全 1.0。
      regionScale: prefRegionScale(p?.regionScale),
    };
    // 迁移过的老值当场写回：不然 `pi.prefs` 会永远停在旧 id 上，每开一次都要现算一次。
    if (p?.theme !== next.theme || p?.macAccent !== next.macAccent || p?.accentTone !== next.accentTone || p?.accent !== undefined || p?.text !== undefined) savePrefs(next);
    return next;
  } catch {
    return { ...DEFAULT_PREFS, regionScale: regionScaleDefault(), lang: detectLang() };
  }
}

/**
 * 带小样的主题 chip（设置抽屉与首跑弹窗共用一个，别再各抄一遍）：点一下立即换上并写回偏好。
 * `scope` 返回「哪些 chip 的亮着状态要一起改」—— 抽屉里是整张 sheet，弹窗里是那张弹窗。
 */
function themeChipEl(t: ThemeInfo, current: ThemeId, scope: () => ParentNode | null, onPick: (id: ThemeId) => void): HTMLElement {
  const chip = el("button", `chip theme-chip${current === t.id ? " on" : ""}`) as HTMLButtonElement;
  chip.type = "button";
  chip.dataset.theme = t.id;
  chip.title = tr(t.label);
  const demo = el("span", "theme-demo");
  demo.style.setProperty("--td-bg", t.demo.bg);
  demo.style.setProperty("--td-panel", t.demo.panel);
  demo.style.setProperty("--td-text", t.demo.text);
  demo.style.setProperty("--td-line", t.demo.line);
  demo.append(el("span", "td-side"), el("span", "td-l1"), el("span", "td-l2"), el("span", "td-btn"));
  demo.classList.add("mac");
  demo.append(el("span", "td-lights"));
  chip.append(demo, el("span", "theme-chip-label", tr(t.label)));
  chip.onclick = () => {
    onPick(t.id);
    for (const other of scope()?.querySelectorAll<HTMLElement>(".theme-chip") ?? []) other.classList.toggle("on", other.dataset.theme === t.id);
  };
  return chip;
}

function savePrefs(prefs: Prefs): void {
  try {
    localStorage.setItem("pi.prefs", JSON.stringify(prefs));
  } catch {
    // private mode: settings just won't be remembered.
  }
}

type ViewerPane = "browse" | "preview" | "edit" | "translate";

/** 预览里的翻译：和 2 MB 的手改上限不同，翻一份只到 512 KB（桥的 `MAX_TRANSLATE_BYTES`）。 */
const MAX_TRANSLATE_BYTES = 512 * 1024;

/** D70: one open shell — its xterm, its body, its tab button. */
interface TermTab {
  id: string;
  shell: string;
  cwd: string;
  term: Terminal;
  fit: FitAddon;
  body: HTMLElement;
  tab: HTMLButtonElement;
}

/** D93: 终端 dialog 的几何，一律用「布局 px」（`#app` 的 zoom 之前的值），存在 `pi.termGeom`。 */
interface TermGeom {
  l?: number;
  t?: number;
  w?: number;
  h?: number;
}

/** 一次拖拽开始时的快照（同上，布局 px）。 */
interface TermBox {
  l: number;
  t: number;
  w: number;
  h: number;
}

/** 浏览器里能改的上限；桥端 `preview.ts` 的 MAX_EDIT_BYTES 必须与它一致。 */
const MAX_EDIT_BYTES = 2 * 1024 * 1024;

interface Viewer {
  root: HTMLElement;
  head: HTMLElement;
  body: HTMLElement;
  sessionId: string;
  path: string;
  info: PreviewInfo | null;
  error: string;
  text: string | null;
  mode: "render" | "source";
  full: boolean;
  /** 浏览（走目录）/ 预览（现有五种 kind）/ 编辑（文本写回，D50）。 */
  pane: ViewerPane;
  /** 编辑中的草稿；重绘时用它而不用磁盘上那份。 */
  draft: string | null;
  dirty: boolean;
  /** 浏览态停在哪；下次打开接着来。 */
  lastDir: string;
  /** 409 冲突说明，有值就显示冲突条。 */
  conflict: string | null;
  /** 当前挂着的 html iframe；只看它发来的 postMessage（D63）。 */
  frame: HTMLIFrameElement | null;
  /** iframe 里**实际显示**的文件与它当初用哪个 token 取的。导航后两者都会变，
   *  所以不能拿 v.info 现算（D63）。 */
  framePath: string;
  frameToken: string;
  /** 外链 / 越界占位：这一格没法在应用里预览，只给个出口。 */
  ext: { url: string; label: string } | null;
  /** 回到一步 html 预览时要回放的滚动位置，等 iframe load 再发（D63）。 */
  pendingScroll: number;
  /** 这一份的翻译状态（D245）；没翻过是 null，换文件就丢。 */
  tr: TrView | null;
  /** 轮询翻译进度的定时器。 */
  trTimer: number | null;
  /** 从父弹层（Everything / 附件 / 产物 / 设置 / Jira 等）新打开浮窗时，历史栈里的入口下标；-1 表示非父层打开。 */
  parentFloor: number;
}

/** 预览历史里的一步（D63）。`browseDir` 表示浏览态的某一个目录；`path` 为空且非浏览态表示「外链 / 越界」。 */
interface VStep {
  path: string | null;
  /** 浏览态（文件管理器目录列表）：返回时切回浏览页并落回这个目录。 */
  browseDir?: string;
  /** 外链占位项：记下当时的 url，前进回来时给个出口。 */
  url?: string;
  label?: string;
  /** 离开这一步时滚到哪儿，返回时回放。 */
  y?: number;
}

const PERM_MODES: { id: PermissionMode; icon: IconName; label: string; desc: string }[] = [
  { id: "readonly", icon: "lock", label: tr("只读"), desc: tr("只放行读文件 / 搜索 / 列目录这类只看的工具，写文件、执行命令、MCP 与扩展工具一律拦下（适合先出方案）") },
  { id: "strict", icon: "pointer", label: tr("逐个确认"), desc: tr("写文件、执行命令、调用 MCP / 扩展工具都要你批准；只看的工具不用") },
  { id: "ask", icon: "shield", label: tr("危险时确认"), desc: tr("只拦删除、push、装依赖、写项目外文件等危险操作（默认）") },
  { id: "auto", icon: "bolt", label: tr("全自动"), desc: tr("不拦截任何操作，风险自负") },
];

type PermMode = (typeof PERM_MODES)[number];

/** One mode by id; an id a stale file names falls back to pi's default (`ask`, D161). */
function permMode(id: string): PermMode {
  for (const m of PERM_MODES) if (m.id === id) return m;
  for (const m of PERM_MODES) if (m.id === "ask") return m;
  // Unreachable: the literal above always contains `ask`.
  return { id: "ask", icon: "shield", label: tr("危险时确认"), desc: "" };
}

type PasteBlock = { text: string; open: boolean };
type Draft = { text: string; images: PendingImage[]; pastes: PasteBlock[] };

/** D163: 附件弹层按会话记目录，最多留这么多条（删掉的会话不该一直占着键）。 */
const ATTACH_DIR_INDEX = "pi.attachDir.index";
const ATTACH_DIR_KEEP = 30;

/** 预览返回栈最多记多少步（D63）。超了就丢掉最早的一步，和浏览器一样。 */
const HISTORY_MAX = 60;

function loadDrafts(): Map<string, Draft> {
  const map = new Map<string, Draft>();
  try {
    const raw = JSON.parse(localStorage.getItem("pi.drafts") ?? "[]");
    if (Array.isArray(raw)) {
      for (const [id, text, pastes] of raw) {
        if (typeof id !== "string" || typeof text !== "string") continue;
        const blocks = Array.isArray(pastes) ? pastes.filter((p): p is string => typeof p === "string").map((p) => ({ text: p, open: false })) : [];
        map.set(id, { text, images: [], pastes: blocks });
      }
    }
  } catch {
    /* corrupt: start clean */
  }
  return map;
}

function rawUrl(info: PreviewInfo): string {
  return `/raw/${info.token}/${info.rel}`;
}

/** 日志正文里的链接是相对仓库根写的：会话 cwd 不在那个仓库里也得点得开（D195）。 */
function resolveFromRoot(root: string, p: string): string {
  let target = p;
  try {
    target = decodeURIComponent(p);
  } catch {
    /* keep */
  }
  if (/^[A-Za-z]:[\\/]/.test(target) || target.startsWith("/") || target.startsWith("\\")) return target;
  if (!root) return target;
  const sep = root.includes("\\") ? "\\" : "/";
  return `${root.replace(/[\\/]+$/, "")}${sep}${target.replace(/[/\\]+/g, sep)}`;
}

/** A link inside a previewed document is relative to that document, not to the session cwd. */
function resolveFrom(docAbs: string, p: string): string {
  let target = p;
  try {
    target = decodeURIComponent(p);
  } catch {
    /* keep */
  }
  if (/^[A-Za-z]:[\\/]/.test(target) || target.startsWith("/") || target.startsWith("\\")) return target;
  const sep = docAbs.includes("\\") ? "\\" : "/";
  const dir = docAbs.slice(0, Math.max(docAbs.lastIndexOf("\\"), docAbs.lastIndexOf("/")));
  return `${dir}${sep}${target.replace(/[\\/]/g, sep)}`;
}

/** 页面里的外链只认 http(s)：`javascript:` / `file:` / 自定义协议一律当没给。 */
/** 同一个文件的两种写法（\\ 与 /）算同一份。 */
/** D388：同一份文件的不同写法（分隔符、大小写、尾斜杠）归一成一个键。 */
function normPath(p: string | null | undefined): string {
  return (p ?? "").replace(/\\/g, "/").replace(/\/+$/, "").toLowerCase();
}

function samePath(a: string | null | undefined, b: string | null | undefined): boolean {
  const na = normPath(a);
  return na !== "" && na === normPath(b);
}

function safeExternalUrl(raw: string): string | null {
  let u: URL;
  try {
    u = new URL(raw);
  } catch {
    return null;
  }
  if (u.protocol !== "http:" && u.protocol !== "https:") return null;
  return u.href;
}

function hostOf(raw: string): string {
  try {
    return new URL(raw).host || raw.slice(0, 80);
  } catch {
    return raw.slice(0, 80);
  }
}

/** `/raw/<token>/<rel>` 里的 rel 换成绝对路径（root 来自 PreviewInfo，D63）。 */
function absFromRel(root: string, rel: string): string {
  const sep = root.includes("\\") ? "\\" : "/";
  let out = root.replace(/[\\/]+$/, "");
  for (const seg of rel.split("/")) {
    if (!seg || seg === ".") continue;
    if (seg === "..") {
      out = out.replace(/[\\/][^\\/]+$/, "");
      continue;
    }
    out += sep + seg;
  }
  return out;
}

/** Last segment of a path, for a tab label ("pwsh · pi-web-client"). */
const shortDir = (p: string): string => p.split(/[\\/]/).filter(Boolean).pop() ?? p;

function fmtSize(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1024 * 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`;
  return `${(n / 1024 / 1024 / 1024).toFixed(1)} GB`;
}

/** 运行时面板里的一行「闲了多久」（D120 / #77）：秒 / 分 / 时三个粒度就够，单位走词典。 */
function idleLabel(ms: number): string {
  if (ms < 60_000) return tr("{p1} 秒", { p1: fmtNum(Math.max(0, Math.round(ms / 1000))) });
  if (ms < 3_600_000) return tr("{p1} 分钟", { p1: fmtNum(Math.round(ms / 60_000)) });
  return tr("{p1} 小时", { p1: fmtNum(Math.round(ms / 3_600_000)) });
}

/** D120 / #78：运行时阈值的两个单位。GB 与 `fmtSize` 同一套（1024 进制）。 */
const MINUTE_MS = 60_000;
const GB = 1024 ** 3;

/**
 * 面板上的一个阈值输入（单位 → 毫秒 / 字节）。空、非数字、0、负数都不算数：它们会把阈值变成
 * 「立刻回收」，比旧值糟糕得多。
 */
function thresholdOf(text: string, unit: number, opts: { allowZero?: boolean } = {}): number | null {
  const raw = text.trim();
  const value = Number(raw);
  if (raw === "" || !Number.isFinite(value)) return null;
  if (opts.allowZero ? value < 0 : value <= 0) return null;
  return Math.round(value * unit);
}

/** 输入框里显示的当前值：没有必要的小数就不写（30 / 2.5，而不是 30.00）。 */
function plainNumber(n: number): string {
  return String(Number(n.toFixed(2)));
}

/** 阈值输入框正在被输入时，别让 tick 广播把面板重画掉（换掉 DOM 就是丢光标、丢草稿）。 */
function runtimeThresholdFocused(): boolean {
  const active = document.activeElement;
  return active instanceof HTMLElement && Boolean(active.closest(".runtime-threshold"));
}

/**
 * 「全部休眠」的回执说人话（D120 / #80）：睡了几个，以及**点名**哪几个还在跑 —— 用户得能确认
 * 自己没有把任务弄丢，而不是看到一个「完成」。
 */
function sleepAllText(receipt: SleepAllReceipt): string {
  const names = receipt.skipped.map((s) => s.name || s.id).join(tr("、"));
  const slept = receipt.slept.length;
  if (!slept && !names) return tr("没有可以休眠的会话：本来就都是空的。");
  if (!names) return tr("已休眠 {p1} 个会话。", { p1: slept });
  if (!slept) return tr("一个都没睡：{p1} 还在跑，没有动。", { p1: names });
  return tr("已休眠 {p1} 个会话；{p2} 还在跑，没有动。", { p1: slept, p2: names });
}

function viewerLoading(text: string): HTMLElement {
  const box = el("div", "viewer-msg");
  box.append(el("span", "act-spin"), el("span", "", text));
  return box;
}

type TimeBucket = "today" | "week" | "older";

interface MgrView {
  q: string;
  origin: "all" | "web" | "cli";
  status: "all" | "active" | "pin" | "normal" | "archived";
  time: "all" | TimeBucket;
  cwd: string;
  group: "none" | "cwd" | "origin" | "status" | "time";
  sort: "updated" | "created" | "name" | "cwd";
  desc: boolean;
}

function defaultMgrView(): MgrView {
  return { q: "", origin: "all", status: "all", time: "all", cwd: "", group: "none", sort: "updated", desc: true };
}

function loadMgrView(): MgrView {
  try {
    const raw = JSON.parse(localStorage.getItem("pi.mgr") ?? "null");
    if (raw && typeof raw === "object") return { ...defaultMgrView(), ...raw };
  } catch {
    /* corrupt or unavailable */
  }
  return defaultMgrView();
}

function loadCollapsedGroups(): string[] {
  try {
    const raw = JSON.parse(localStorage.getItem("pi.mgrCollapsed") ?? "[]");
    if (Array.isArray(raw)) return raw.filter((k): k is string => typeof k === "string");
  } catch {
    /* corrupt or unavailable */
  }
  return [];
}

/** 本周 starts on Monday, local time. */
function timeBucket(ts: number): TimeBucket {
  const day = new Date();
  day.setHours(0, 0, 0, 0);
  if (ts >= day.getTime()) return "today";
  const monday = new Date(day);
  monday.setDate(day.getDate() - ((day.getDay() + 6) % 7));
  return ts >= monday.getTime() ? "week" : "older";
}

/** First `max` characters of a single line, with an ellipsis when it had to be cut. */
function oneLine(text: string, max: number): string {
  const flat = text.replace(/\s+/g, " ").trim();
  return flat.length > max ? `${flat.slice(0, max)}…` : flat;
}

/** The tail of a stream: what just scrolled by matters, the beginning rarely does. */
function tailText(text: string, maxLines: number, maxChars: number): string {
  const lines = text.replace(/\r/g, "").split("\n").filter((line) => line.trim());
  if (!lines.length) return "";
  let tail = lines.slice(-maxLines).join("\n");
  if (tail.length > maxChars) tail = `…${tail.slice(-maxChars)}`;
  return tail;
}

/** 会话列表的时间戳：一分钟内「刚刚」，其余交给 Intl（D110）。 */
function relativeTime(ts: number): string {
  return fmtRelative(ts);
}

/** 刻度尺的步长（分钟）：挑一个让格子数落在 2–11 之间的，再长就上台阶。 */
const RULER_STEPS = [1, 2, 5, 10, 15, 30, 60, 120, 240];

/** 跑了多久，写成 m:ss（过一小时是 h:mm:ss）—— 只进刻度尺的 tooltip，不占版面。 */
function clockText(totalSecs: number): string {
  const s = totalSecs % 60;
  const m = Math.floor(totalSecs / 60) % 60;
  const h = Math.floor(totalSecs / 3600);
  const mm = String(m).padStart(2, "0");
  const ss = String(s).padStart(2, "0");
  return h ? `${h}:${mm}:${ss}` : `${m}:${ss}`;
}

/**
 * 一把刻度尺：一条 1px 竖线是一格，格子攒得越多说明跑得越久，最右那条是「现在」。
 * 位置等距铺满卡片宽度、不按时间比例画 —— 那会变成一根永远不满的进度条，而进度条会被读成
 * 「快完成了」，agent 跑多久并没有完成度可言。密度本身就是读数，具体时长留在 tooltip。
 */
function drawRuler(node: HTMLElement, since: number): void {
  const secs = Math.max(0, Math.floor((Date.now() - since) / 1000));
  const mins = secs / 60;
  const step = RULER_STEPS.find((x) => mins / x <= 11) ?? 240;
  const marks = Math.floor(mins / step);
  node.title = tr("已经跑了 {p1}", { p1: clockText(secs) });
  const key = `${step}/${marks}`;
  if (node.dataset.key === key) return;
  node.dataset.key = key;
  node.replaceChildren(...Array.from({ length: marks + 1 }, (_, i) => el("i", i === marks ? "now" : "")));
}

function urlBase64ToUint8Array(base64: string): Uint8Array {
  const padding = "=".repeat((4 - (base64.length % 4)) % 4);
  const raw = atob((base64 + padding).replace(/-/g, "+").replace(/_/g, "/"));
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i += 1) out[i] = raw.charCodeAt(i);
  return out;
}

/** "⌘V" on Apple hardware, "Ctrl+V" everywhere else. */
const PASTE_KEY = /Mac|iPhone|iPad|iPod/.test(`${navigator.platform} ${navigator.userAgent}`) ? "⌘V" : "Ctrl+V";

/** #106: 表格类文件即使读不了（.xls/.ods/加密包），也用「这个格式这里不支持」而不是通用二进制文案。 */
const DESKTOP_OPEN = /\.(xlsx|xlsm|xlsb|xls|ods|pptx|pptm|ppsx|potx|ppt|pps|pdf|doc|docx|mp4|m4v|webm|ogv|mov|mkv|avi|wmv|flv|mp3|wav|m4a|aac|ogg|oga|flac|opus)$/i;

/** #542: stop whatever video / audio is in this subtree before it is torn down — no sound from a
 * panel the user already moved away from, and no half-open range request keeping the file busy
 * (clearing `src` + `load()` releases the decoder and the connection). */
function stopMedia(root: ParentNode): void {
  for (const m of root.querySelectorAll<HTMLMediaElement>("video, audio")) {
    try {
      m.pause();
      m.onerror = null;
      m.removeAttribute("src");
      m.load();
    } catch {
      /* already gone */
    }
  }
}

/** "Deepseek-V4.1-Flash · x0.11 · 1M" -> "Deepseek-V4.1-Flash": the chip has no room for pricing. */
function shortModelName(name: string): string {
  return name.split(" · ")[0] ?? name;
}

/**
 * 模型的身份是 `provider/id`，不是 id。两个 provider 可以卖同一个 id —— 本机 `wb2api`（远端网关）
 * 与 `wb2_mac`（本机网关）就各有一份 `cn:glm-5.4`。只按 id `find()` 会稳定命中目录里的第一个，
 * 于是「挑的是本机那份」在确认时被换成另一个来源：评审就这么被派到掉线的网关上（D454）。
 *
 * 任一边 provider 为空时按「同一个」算 —— 这是**向后兼容**（老桥的 `SessionState` 没有 provider、
 * 老记录只存了 id），不是「通配任意来源」：空串只是「这边不知道」，而不是「哪边都行」。
 *
 * 它只回答「目录里这一行可能就是那个模型吗」（解决 id→行）；**不回答**「两个选择是不是同一个」——
 * 后者（换没换、该发 setModel 吗）必须严格比 provider+id，见 `openModelSheet()` 里的
 * `isDraft` / `isStart` / `moved()`。两边 provider 都知道时这里也是严格比：``a.provider === b.provider``。
 */
function sameModel(a: { provider?: string; id?: string }, b: { provider?: string; id?: string }): boolean {
  if (!a.id || !b.id) return false;
  if (a.id !== b.id) return false;
  // 有一边不知道 provider（老桥 / 老记录）时按「同一个」算：没有更细的信息，别把用户挡在外面。
  return !a.provider || !b.provider || a.provider === b.provider;
}

/**
 * wb2api 的目录把倍率塞在模型名里：`Kimi-K3 · x1.62 · 1M`。倍率是计费口径，不是名字的一部分，
 * 弹窗和 chip 要分开摆，所以单独取出来；没有倍率段的目录（自定义 provider）返回空串。
 */
function modelMultiplier(name: string): string {
  return name.split(" · ").find((part) => /^x[-\d.]+$/i.test(part.trim()))?.trim() ?? "";
}

/** 192000 -> "192K", 1000000 -> "1M". */
function compactSize(n?: number): string {
  // 0 与 undefined 不一样：会话刚开、还没跑过一轮时上下文就是 0，chip 上要显示「0/1M」而不是「/1M」。
  if (n == null || Number.isNaN(n)) return "";
  if (n === 0) return "0";
  if (n >= 1_000_000) return `${Math.round(n / 100_000) / 10}M`;
  return `${Math.round(n / 1000)}K`;
}

/** #484：桥回的错误码 → 一句人话。 */
function policyErrorText(error: any): string {
  const code = String(error?.code ?? "");
  const field = String(error?.field ?? "");
  if (code === "range") {
    return field === "handoff" ? tr("自动交接阈值要在 5% 到 90% 之间") : tr("自动压缩阈值要在 5% 到 90% 之间");
  }
  if (code === "equal") return tr("两条阈值不能相同：同一时间只能执行其中一个");
  if (code === "gap") return tr("两条阈值至少要差 5 个百分点");
  if (code === "skill") return tr("没装 handoff 技能（/skill:handoff）：自动交接用不了");
  return String(error?.message ?? error ?? tr("保存失败"));
}

/** #484：子弹窗保存前的本地校验（和桥同一条规则，省一次往返）。 */
/**
 * 本地先拦一次明显的错（省一次往返）。**桥才是权威**：它按解析后的两条线校验
 * （会话覆盖可能与项目的另一条线撞车），所以这里只判「都显式填了」的情形。
 */
function validatePolicyDraft(compact: number | null, handoff: number | null, handoffOn: boolean): string | null {
  for (const [value, which] of [
    [compact, "compact"],
    [handoffOn ? handoff : null, "handoff"],
  ] as const) {
    if (value == null) continue;
    if (!Number.isFinite(value) || value < 5 || value > 90) {
      return which === "handoff" ? tr("自动交接阈值要在 5% 到 90% 之间") : tr("自动压缩阈值要在 5% 到 90% 之间");
    }
  }
  if (compact != null && handoffOn && handoff != null && Math.abs(compact - handoff) < 5) {
    return Math.abs(compact - handoff) === 0
      ? tr("两条阈值不能相同：同一时间只能执行其中一个")
      : tr("两条阈值至少要差 5 个百分点");
  }
  return null;
}
